import {helpLabel} from './help-tooltip.mjs';
import {renderDataTable} from './data-table.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const variants=[['raw','저장 본문'],['metadata','분류 메타데이터'],['hybrid','메타데이터·근거 발췌']];
const statusLabel={PLANNED:'실행 대기',RUNNING:'실행 중',COMPLETED:'완료',PARTIAL:'일부 완료',ACTION_REQUIRED:'호출 결과 확인 필요',RESERVED:'응답 대기',FAILED:'실패',OUTCOME_UNKNOWN:'응답 확인 필요',INCOMPARABLE:'모델 변경 · 비교 제외'};
const button=(label,action,id='',extra='')=>`<button type="button" class="button small" data-studio-action="news-${action}" data-studio-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
const raw=(value,label)=>`<details class="spaced"><summary>${esc(label)}</summary><pre class="code">${esc(JSON.stringify(value,null,2))}</pre></details>`;
const date=value=>value?new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' KST':'—';
export function newsComparisonDetailMarkup(experiment){
 const e=experiment,repeats=e.budget.plannedDecisionCalls/(e.snapshots.length*3),blocked=e.attempts.some(a=>['RESERVED','OUTCOME_UNKNOWN'].includes(a.status));
 const rows=e.snapshots.flatMap(s=>Array.from({length:repeats},(_,i)=>variants.map(([variant,label])=>{
  const a=e.attempts.find(a=>a.snapshotId===s.id&&a.variant===variant&&a.repetition===i+1),available=!a&&!blocked&&e.budget.reservedCalls<e.budget.maxDecisionCalls;
  return [`${esc(label)}<small class="studio-cell-secondary">${i+1}회차</small>`,esc(a?statusLabel[a.status]||a.status:'대기'),`${esc(a?.decision?.action?.toUpperCase()||'—')}${Number.isFinite(a?.decision?.confidence)?' · '+(a.decision.confidence*100).toFixed(1)+'%':''}`,esc(a?.provider?.model||'—'),a?.resultId?button('요청·응답','result',a.resultId):button('JEV 1회 실행','run',e.id,`data-news-snapshot="${esc(s.id)}" data-news-variant="${variant}" data-news-repetition="${i+1}" ${available?'':'disabled'}`)];
 })).flat());
 return `<div>${helpLabel('비교 조건','정책·가격·계좌를 고정하고 뉴스 입력 방식만 바꿔 JEV의 결정을 비교합니다.')}</div><p class="tiny muted">비교 대상 ${esc(e.snapshots.map(s=>s.sources.map(x=>x.title).join(', ')).join(' · '))}</p><div class="detail-row"><span>호출 한도 / 예약 / 완료</span><strong>${e.budget.maxDecisionCalls} / ${e.budget.reservedCalls} / ${e.budget.completedCalls}</strong></div><div class="detail-row"><span>결과 범위</span><strong>매매 결정·운용 강도</strong></div><div class="detail-row"><span>호출 비용</span><strong>요율 연결 필요</strong></div>${blocked?'<p class="error-text">저장된 호출의 응답 상태를 확인하세요. 결과가 확인되면 다음 비교를 진행할 수 있습니다.</p>':''}${renderDataTable(['입력 방식','진행','결정·확신도','응답 모델','실행·원본'],rows)}${e.pairedResults.map(p=>`<p class="spaced">${p.repetition}회차: 매매 결정 ${p.sameAction?'일치':'차이'}, 투자 태도 ${p.sameStance?'일치':'차이'}</p>`).join('')}${raw(e,'비교 조건과 저장 기록')}`;
}
export function createNewsComparisonUI({request,mutate,open,download,getMindId,getRecordsHref=()=>'',form,getDialogToken=()=>0}){
 let sources=null,current=null,pending=false,viewSequence=0;
 const beginView=title=>{if(title)open(title,'<p data-news-read-pending role="status" aria-live="polite">저장된 비교 자료를 불러오는 중…</p>');return {host:getDialogToken(),sequence:++viewSequence};};
 const currentView=token=>token.host===getDialogToken()&&token.sequence===viewSequence;
 async function readView(action,id,path,token,title='뉴스 입력 비교'){try{const value=await request(path);return currentView(token)?value:null;}catch(problem){if(currentView(token))open(title,'<p class="error-text" role="alert">'+esc(problem.message||'비교 자료를 불러오지 못했어요.')+'</p>',button('다시 조회',action,id));return null;}}
 const recordsLink=()=>{const href=getRecordsHref();return href?'<a class="button" data-studio-route href="'+esc(href)+'">모의 판단 기록 열기</a>':'';};
 async function detail(id,token=beginView('뉴스 입력 비교')){const value=await readView('detail',id,'/api/workspace/news-comparisons?'+new URLSearchParams({id}),token);if(!value)return;current=value.experiment;open('뉴스 입력 비교',newsComparisonDetailMarkup(current),button('비교 목록','list')+button('새로고침','detail',id)+button('비교 기록 내보내기','export',id));}
 async function list(){const token=beginView('뉴스 입력 비교'),value=await readView('list','','/api/workspace/news-comparisons?'+new URLSearchParams({mindId:getMindId()||'all'}),token);if(!value)return;open('뉴스 입력 비교',value.items.length?renderDataTable(['대상 자료','생성 시각','진행','작업'],value.items.map(e=>[esc(e.snapshots.flatMap(s=>s.sources.map(d=>d.title)).join(', ')),esc(date(e.createdAt)),esc(statusLabel[e.status]||e.status),button('비교 열기','detail',e.id)])):'<p class="empty">비교 기록이 없습니다. 뉴스·경제 발표가 전달된 모의 판단 상세에서 「JEV 뉴스 입력 비교」를 선택하세요.</p>',recordsLink());}
 async function create(runId){const token=beginView('뉴스 입력 비교'),value=await readView('create',runId,'/api/workspace/news-comparisons/source?'+new URLSearchParams({runId}),token);if(!value)return;sources=value;if(!sources.documents.length)return open('뉴스 입력 비교','<p class="empty">이 결정에 전달된 승인 뉴스·경제 발표가 없습니다. 라이브러리의 뉴스·경제 발표 자료를 마인드에 연결한 뒤, 새 결정의 입력 자료를 확인하세요.</p>');const d=sources.documents[0];form('뉴스 입력 비교 만들기','news-create',`<label class="field full">실제 전달된 뉴스·경제 발표<select name="documentId" data-news-document>${sources.documents.map(d=>`<option value="${esc(d.id)}">${esc(d.title)}</option>`).join('')}</select></label><label class="field full">저장 본문<textarea data-news-body readonly rows="8">${esc(d.body)}</textarea></label><label class="field full">비교할 근거 구절<textarea name="excerptText" required maxlength="12000" rows="4" placeholder="위 본문에서 근거 구절을 그대로 복사하세요."></textarea></label><label class="field">방식별 반복 횟수<input name="repetitions" type="number" value="1" min="1" max="10" required></label><div class="full tiny">${helpLabel('비교 방식 3종','저장 본문, 분류 정보, 분류 정보와 근거 발췌를 비교합니다.')} · 호출 한도: 반복 횟수 × 3 · 실행당 1회</div>`,runId,'비교 계획 저장');}
 async function click(action,id,node){
  if(action==='news-list')return list();if(action==='news-create')return create(id);if(action==='news-detail')return detail(id);
  if(action==='news-run'){if(pending)throw new Error('진행 중인 비교 응답을 기다려 주세요.');pending=true;const token=beginView();try{const value=await readView('detail',id,'/api/workspace/news-comparisons?'+new URLSearchParams({id}),token);if(!value)return;current=value.experiment;await mutate('',{id,snapshotId:node.dataset.newsSnapshot,variant:node.dataset.newsVariant,repetition:Number(node.dataset.newsRepetition),comparisonRevision:current.revision,optInJev:true},'/api/workspace/news-comparisons/run');if(!currentView(token))return;return await detail(id,token);}catch(problem){if(currentView(token))throw problem;}finally{pending=false;}}
  if(action==='news-result'){const token=beginView('비교 요청·응답'),value=await readView('result',id,'/api/workspace/news-comparisons?'+new URLSearchParams({resultId:id}),token,'비교 요청·응답');if(!value)return;open('비교 요청·응답',raw(value.result,'실제 요청·응답과 사용량'),button('원본 내보내기','result-export',id));}
  if(action==='news-export'||action==='news-result-export'){const value=await request('/api/workspace/news-comparisons?'+new URLSearchParams(action==='news-export'?{id}:{resultId:id}));download?.('chung-ji-'+id+'.json',JSON.stringify(value,null,2),'application/json');}
 }
 async function submit(data,runId){const token=beginView(),repetitions=Number(data.get('repetitions')),value=await mutate('',{runId,documentId:data.get('documentId'),excerptText:data.get('excerptText'),repetitions,maxDecisionCalls:repetitions*3},'/api/workspace/news-comparisons/create');if(!currentView(token))return;await detail(value.experiment.id,token);}
 function change(target){if(!target.matches?.('[data-news-document]'))return;const d=sources?.documents.find(d=>d.id===target.value),f=target.closest('form');if(d&&f){f.querySelector('[data-news-body]').value=d.body;f.elements.excerptText.value='';}}
 return {click,submit,change};
}
